#!/bin/bash
# BITS reports update v8: quieter style, growing report page, denser overview, fuller top bar (builds on the native rebuild, no copied classic
# code), a typed API layer written from the backend, live updates everywhere, inbox, list +
# detail pane, report wizard, student tracker, and the phone layout with a bottom tab bar.
# Includes everything from v6, so it works whether or not v6 was installed.
#
#   bash bits-update-v8.sh                      (uses the usual project folder)
#   bash bits-update-v8.sh /path/to/project     (or say where the project is)
#
# Every file it changes or removes is first saved to _backups/before-v8-<time>.tar.gz.
set -e
SELF="$(cd "$(dirname "$0")" && pwd)/$(basename "$0")"   # before any cd: the payload is read from this file
DEFAULT="$HOME/Documents/date.29.10.206OOPSproject"
DIR="${1:-$DEFAULT}"
cd "$DIR" 2>/dev/null || { echo "Can't find the project at $DIR. Run: bash $0 /path/to/project"; exit 1; }
[ -f start.sh ] && [ -d frontend-next ] && [ -d backend ] || { echo "$DIR doesn't look like the BITS reports project (no start.sh / frontend-next / backend)."; exit 1; }

CHANGED="README.md
backend/app/domain/appearance.py
backend/app/models/schemas.py
