STAMP=$(date +%Y%m%d-%H%M%S)
mkdir -p _backups
EXISTING=$(for f in $CHANGED $DELETED; do if [ -e "$f" ]; then echo "$f"; fi; done)
if [ -n "$EXISTING" ]; then tar czf "_backups/before-v8-$STAMP.tar.gz" $EXISTING; fi
echo "Backup of the current files: _backups/before-v8-$STAMP.tar.gz"

TMP=$(mktemp -d)
sed -n '/^__PAYLOAD__$/,$p' "$SELF" | tail -n +2 | python3 -c 'import base64,sys; sys.stdout.buffer.write(base64.b64decode(sys.stdin.read()))' > "$TMP/payload.tar.gz"
tar xzf "$TMP/payload.tar.gz" -C "$DIR"
for f in $DELETED; do if [ -e "$f" ]; then rm -f "$f"; fi; done
for d in frontend-next/src/classic frontend-next/scripts; do if [ -d "$d" ]; then find "$d" -type d -empty -delete 2>/dev/null || true; fi; done
rm -rf "$TMP"
echo "Updated $(echo "$CHANGED" | wc -w | tr -d ' ') files, removed old ones where present."
echo
echo "Next: stop the app if it's running (Ctrl+C), then run   ./start.sh"
echo "The first start updates the packages (about a minute). Then open http://localhost:3000"
exit 0
